mapper.select:
SELECT /* getServiceInfoContentList */ SVCI_CNTN
  FROM CT_SVINFO
 WHERE CATE_CGRP = #{cateCgrp}
   AND CATE_CODE = #{cateCode}
UNION ALL
SELECT SVCI_ENCT
  FROM CT_SVINFO
 WHERE CATE_CGRP = #{cateCgrp}
   AND CATE_CODE = #{cateCode}
   AND SVCI_ENCT IS NOT NULL

SELECT /* getServiceInfoCategoryCnt */ COUNT(1)
  FROM TB_CODEXD
 WHERE COMM_CODE = #{cateCgrp}
   AND COMD_CODE = #{cateCode}
   AND USEE_YSNO = #{useeYsno}

SELECT /* getServiceInfoCnt */ COUNT(1)
  FROM CT_SVINFO
 WHERE CATE_CGRP = #{cateCgrp}
   AND CATE_CODE = #{cateCode}

SELECT /* getServiceInfoOrigAudit */ REGI_ADMN, REGI_DATE
  FROM CT_SVINFO
 WHERE CATE_CGRP = #{cateCgrp}
   AND CATE_CODE = #{cateCode}
   AND VERS_NUMB = 1

mapper.insert:
INSERT /* setServiceInfo */
  INTO CT_SVINFO (
       CATE_CGRP, CATE_CODE, VERS_NUMB, SVCI_TITL, SVCI_ENTL, SVCI_CNTN, SVCI_ENCT, DPLY_YSNO
     , REGI_ADMN, REGI_DATE, UPDT_ADMN, UPDT_DATE
) VALUES (
       #{cateCgrp}, #{cateCode}, #{versNumb}, #{svciTitl}, #{svciEntl}, #{svciCntn}, #{svciEnct}, #{dplyYsno}
     , #{regiAdmn}, COALESCE(#{regiDate,jdbcType=TIMESTAMP}, CURRENT_TIMESTAMP)
     , #{updtAdmn,jdbcType=BIGINT}
     , CASE WHEN #{updtAdmn,jdbcType=BIGINT} IS NULL THEN NULL ELSE CURRENT_TIMESTAMP END
)

mapper.update:
UPDATE /* uptServiceInfo */ CT_SVINFO
   SET SVCI_TITL = #{svciTitl}
     , SVCI_ENTL = #{svciEntl}
     , SVCI_CNTN = #{svciCntn}
     , SVCI_ENCT = #{svciEnct}
     , UPDT_ADMN = #{updtAdmn}
     , UPDT_DATE = CURRENT_TIMESTAMP
 WHERE CATE_CGRP = #{cateCgrp}
   AND CATE_CODE = #{cateCode}
   AND VERS_NUMB = #{versNumb}
   AND DPLY_YSNO = #{dplyYsno}

UPDATE /* uptServiceInfoDeployOff */ CT_SVINFO
   SET DPLY_YSNO = #{no}
 WHERE CATE_CGRP = #{cateCgrp}
   AND CATE_CODE = #{cateCode}
   AND DPLY_YSNO = #{yes}

UPDATE /* uptServiceInfoDeployOn */ CT_SVINFO
   SET DPLY_YSNO = #{yes}
     , DPLY_ADMN = #{dplyAdmn}
     , DPLY_DATE = CURRENT_TIMESTAMP
 WHERE CATE_CGRP = #{cateCgrp}
   AND CATE_CODE = #{cateCode}
   AND VERS_NUMB = #{versNumb}

mapper.delete:
DELETE /* delServiceInfo */
  FROM CT_SVINFO
 WHERE CATE_CGRP = #{cateCgrp}
   AND CATE_CODE = #{cateCode}
